/**
 * Animar el movimiento de la tarjeta hacia la siguiente etapa.
 *
 * @param {Object} tarjeta_candidato Tarjeta del candidato.
 * @param {Object} etapa_destino Etapa destino.
 * @returns {void}
 * @author Esperanza Olivo
 */
function animarMovimientoEtapaCandidato(tarjeta_candidato, etapa_destino) {
    $('#candidato-animacion-temp').remove();

    var posicion_tarjeta = tarjeta_candidato.offset();
    var ancho_tarjeta = tarjeta_candidato.outerWidth();
    var alto_tarjeta = tarjeta_candidato.outerHeight();
    var scroll_vertical = $(window).scrollTop();

    var contenedor_destino = etapa_destino.find('.candidatos-container').first();
    var destino = contenedor_destino.offset();
    var destino_ancho = contenedor_destino.outerWidth();

    tarjeta_candidato.css('visibility', 'hidden');
    contenedor_destino.find('.mensaje-etapa-vacia').remove();
    contenedor_destino.prepend(tarjeta_candidato);

    var posicion_final = tarjeta_candidato.offset();

    var tarjeta_clon_candidato = tarjeta_candidato.clone().attr('id', 'candidato-animacion-temp').css({
        position: 'fixed',
        top: posicion_tarjeta.top - scroll_vertical,
        left: posicion_tarjeta.left,
        width: ancho_tarjeta,
        height: alto_tarjeta,
        margin: 0,
        zIndex: 9999,
        visibility: 'visible',
        pointerEvents: 'none',
        boxShadow: '0 8px 25px rgba(0,0,0,0.18)'
    });

    $('body').append(tarjeta_clon_candidato);

    tarjeta_clon_candidato.animate({
        top: posicion_final.top - scroll_vertical, 
        left: destino.left + (destino_ancho - ancho_tarjeta) / 2
    }, 180, 'swing', function() {
        tarjeta_clon_candidato.remove();        
        tarjeta_candidato.css('visibility', 'visible');

    });
}

